import{_ as a,o,c as s,a0 as l}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"第 8 章 · 第一个回测","description":"","frontmatter":{},"headers":[],"relativePath":"book/part2/ch8.md","filePath":"book/part2/ch8.md","lastUpdated":1788537144000}'),i={name:"book/part2/ch8.md"};function e(r,t,c,n,p,d){return o(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="第-8-章-·-第一个回测" tabindex="-1">第 8 章 · 第一个回测 <a class="header-anchor" href="#第-8-章-·-第一个回测" aria-label="Permalink to &quot;第 8 章 · 第一个回测&quot;">​</a></h1><div class="ob-meta"><span class="chip">第二篇 · 筑基篇</span><span class="chip">⏱ 实操约 60 分钟</span><span class="chip hot">✅ 框架已发布 · 实操细节写作中</span></div><div class="tip custom-block"><p class="custom-block-title">🎯 学完这章你能</p><ul><li>在聚宽平台从零跑通你的第一个真实数据回测</li><li>理解回测引擎在&quot;替你假装&quot;什么（撮合、成本、成交假设）</li></ul></div><h2 id="先在模拟器里预演一遍" tabindex="-1">先在模拟器里预演一遍 <a class="header-anchor" href="#先在模拟器里预演一遍" aria-label="Permalink to &quot;先在模拟器里预演一遍&quot;">​</a></h2><p>第 0 步的迷你模拟器展示的就是本章要跑的双均线策略。真实回测与它的核心逻辑一模一样，区别只在：<strong>真数据、真代码、真实成本假设</strong>。</p><div class="ob-demo"><iframe src="/demos/backtest.html" loading="lazy" title="迷你回测模拟器"></iframe><div class="cap">双均线策略模拟：MA5 上穿 MA20（金叉）买入，下穿（死叉）卖出。换几次行情，观察策略在不同市场环境下的表现差异。</div></div><h2 id="实操骨架-写作大纲" tabindex="-1">实操骨架（写作大纲） <a class="header-anchor" href="#实操骨架-写作大纲" aria-label="Permalink to &quot;实操骨架（写作大纲）&quot;">​</a></h2><ol><li><strong>注册聚宽 + 界面导览</strong>：研究环境 vs 回测环境</li><li><strong>逐行讲解最小回测代码</strong>（约 40 行）：初始化 → 每日逻辑 → 下单函数——每一行都配&quot;人话注释&quot;</li><li><strong>成本假设</strong>：手续费（佣金+印花税）、滑点——不设成本的回测都是自欺</li><li><strong>跑起来</strong>：看懂回测详情页的每一块：收益曲线、持仓记录、交易明细</li><li><strong>第一次复检</strong>：用第 10 章的清单过一遍自己的代码（预告式演练）</li></ol><div class="tip custom-block"><p class="custom-block-title">💡 为什么选聚宽入门</p><p>在线环境零安装、文档全中文、社区案例多——把新手从&quot;环境配置&quot;这座大山前先绕过去。QMT/Ptrade 等本地化工具的思路相通，以后迁移不难。</p></div><div class="info custom-block"><p class="custom-block-title">📋 本章自查清单（预告）</p><ul><li>[ ] 我独立跑通了一个双均线回测（不是复制粘贴运行，是能逐行讲清楚）</li><li>[ ] 我设置了手续费和滑点，并对比了设置前后的收益差异</li><li>[ ] 我能说出这个策略&quot;赚的是什么钱&quot;（提示：趋势行情的延续性）</li></ul></div><p>→ 下一章：<a href="/book/part2/ch9.html">第 9 章 · 回测报告人话指南</a></p>',11)])])}const m=a(i,[["render",e]]);export{u as __pageData,m as default};
